import { NextResponse } from "next/server";

// POST /api/voice  { text: string, voiceId?: string }
// Returns audio/mpeg generated by ElevenLabs text-to-speech.
//
// If ELEVENLABS_API_KEY is not configured, responds 503 with a JSON flag so the
// client can gracefully fall back to the browser's built-in speech synthesis —
// the demo never breaks, it just uses a less-natural voice.

export const runtime = "nodejs";

const DEFAULT_VOICE = process.env.ELEVENLABS_VOICE_ID || "JBFqnCBsd6RMkjVDRZzb"; // "George" — warm male voice
const MODEL = process.env.ELEVENLABS_MODEL_ID || "eleven_turbo_v2_5";

export async function POST(req) {
  const apiKey = process.env.ELEVENLABS_API_KEY;
  if (!apiKey) {
    return NextResponse.json(
      { fallback: true, reason: "ELEVENLABS_API_KEY not set" },
      { status: 503 }
    );
  }

  let body;
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ error: "invalid JSON" }, { status: 400 });
  }

  const text = (body?.text || "").toString().slice(0, 800);
  if (!text) {
    return NextResponse.json({ error: "missing text" }, { status: 400 });
  }
  const voiceId = body?.voiceId || DEFAULT_VOICE;

  try {
    const res = await fetch(
      `https://api.elevenlabs.io/v1/text-to-speech/${voiceId}`,
      {
        method: "POST",
        headers: {
          "xi-api-key": apiKey,
          "Content-Type": "application/json",
          Accept: "audio/mpeg",
        },
        body: JSON.stringify({
          text,
          model_id: MODEL,
          voice_settings: {
            stability: 0.5,
            similarity_boost: 0.75,
            style: 0.1,
            use_speaker_boost: true,
          },
        }),
      }
    );

    if (!res.ok) {
      const detail = await res.text().catch(() => "");
      return NextResponse.json(
        { fallback: true, reason: `ElevenLabs ${res.status}`, detail: detail.slice(0, 300) },
        { status: 502 }
      );
    }

    const audio = await res.arrayBuffer();
    return new Response(audio, {
      headers: {
        "Content-Type": "audio/mpeg",
        "Cache-Control": "no-store",
      },
    });
  } catch (err) {
    return NextResponse.json(
      { fallback: true, reason: "fetch failed", detail: String(err).slice(0, 300) },
      { status: 502 }
    );
  }
}
